Section AHMNUM.
  Context {HCEIL : HeapCeil}.

  Lemma ahm_numbers : forall TB pd spz,
    4096 <= TB -> TB mod 4096 = 0 -> TB + 0x38e000 <= pd - 8388608 ->
    (TB + 0x38e000 <= 65536 \/ 7241728 <= TB) -> (TB + 0x38e000 <= 2147446784 \/ 17594333495296 <= TB) ->
    pd <= spz < pd + 4096 -> pd mod 4096 = 0 -> hceil = spz - 8388608 ->
    akobj TB 0x38e000 /\ TB + 0x38e000 <= aceil.
